import{_ as a,o as s,c as n,a1 as t}from"./chunks/framework.DaSVVvC-.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md"}'),i={name:"architecture.md"};function o(l,e,c,r,p,d){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>The repository is split by responsibility:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>packages/tokens      Design decisions and generated CSS variables</span></span>
<span class="line"><span>packages/components  Framework-agnostic custom elements and component CSS</span></span>
<span class="line"><span>docs                 Living documentation and examples</span></span>
<span class="line"><span>scripts              Project-level generation and verification scripts</span></span>
<span class="line"><span>examples             Tiny framework portability examples</span></span></code></pre></div><h2 id="token-layer" tabindex="-1">Token Layer <a class="header-anchor" href="#token-layer" aria-label="Permalink to &quot;Token Layer&quot;">​</a></h2><p><code>packages/tokens/src/tokens.json</code> is the source of truth for global, semantic, and theme tokens. The build script resolves references like <code>{global.space.md}</code> and emits:</p><ul><li><code>tokens.css</code> for global and semantic tokens.</li><li><code>theme-default.css</code>, <code>theme-dark.css</code>, and <code>theme-high-contrast.css</code>.</li><li><code>tokens.json</code> for documentation and verification.</li></ul><p>Components consume semantic aliases such as <code>--theme-color-action-primary-bg</code> and <code>--semantic-radius-control</code>, not raw palette trivia.</p><h2 id="component-layer" tabindex="-1">Component Layer <a class="header-anchor" href="#component-layer" aria-label="Permalink to &quot;Component Layer&quot;">​</a></h2><p><code>packages/components/src/components</code> contains the custom elements. Components are intentionally small:</p><ul><li>Attributes define public API.</li><li>Rendering produces semantic HTML.</li><li>CSS consumes tokens through custom properties.</li><li>Metadata in <code>component-definitions.js</code> generates the custom elements manifest.</li></ul><p>The manifest is a documentation contract. If a prop is not documented there, it is not part of the public API.</p><p>Elena is installed and configured in <code>packages/components/elena.config.mjs</code> because the source article uses Elena as the Progressive Web Component build tool. The default project build remains explicit and educational: it copies readable source modules, emits bundled CSS, and writes the manifest from reviewed metadata. The Elena build can be run with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:elena</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace=@my-ds/components</span></span></code></pre></div><p>The remaining migration step is to convert native component classes to <code>Elena(HTMLElement)</code> classes and then promote Elena to the default package build.</p><h2 id="documentation-layer" tabindex="-1">Documentation Layer <a class="header-anchor" href="#documentation-layer" aria-label="Permalink to &quot;Documentation Layer&quot;">​</a></h2><p>VitePress reads generated artifacts from the packages:</p><ul><li><code>custom-elements.json</code> powers component headers and prop tables.</li><li><code>tokens.json</code> powers token tables.</li><li>The same component CSS and token CSS used by consumers are used by docs examples.</li></ul><p>This keeps documentation honest. If the package output breaks, the docs break too.</p><h2 id="build-order" tabindex="-1">Build Order <a class="header-anchor" href="#build-order" aria-label="Permalink to &quot;Build Order&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:tokens</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:lib</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:generate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span></code></pre></div><p>That sequence makes dependencies explicit: docs are downstream of the token and component packages.</p>`,21)])])}const m=a(i,[["render",o]]);export{u as __pageData,m as default};
